describe('Keyboard Navigation - Tab Key Accessibility', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.injectAxe();
  });

  it('should navigate through all interactive elements using Tab key in logical order', () => {
    // Get all focusable elements
    cy.get('button, a, input, select, textarea, [tabindex]:not([tabindex="-1"])').then(($elements) => {
      const focusableElements = $elements.length;
      expect(focusableElements).to.be.greaterThan(0);
    });

    // Start from the beginning
    cy.get('body').tab();
    cy.focused().should('exist');

    // Tab through multiple elements and verify focus moves
    let previousElement = null;
    for (let i = 0; i < 5; i++) {
      cy.focused().then(($focused) => {
        const currentElement = $focused[0];
        expect(currentElement).to.not.equal(previousElement);
        previousElement = currentElement;
      });
      cy.focused().tab();
    }

    // Verify focus is on an interactive element
    cy.focused().should('have.attr', 'tabindex').or('match', 'button, a, input, select, textarea');
  });

  it('should skip elements with tabindex="-1" and maintain focus order', () => {
    // Create test scenario with hidden focusable element
    cy.get('body').then(() => {
      cy.window().then((win) => {
        const style = win.document.createElement('style');
        style.textContent = `
          .skip-focus { tabindex: -1; }
          .visible-focus { outline: 2px solid blue; }
        `;
        win.document.head.appendChild(style);
      });
    });

    // Tab to first element
    cy.get('body').tab();
    cy.focused().should('exist');
    const firstFocusedElement = cy.focused();

    // Tab to next element
    cy.focused().tab();
    cy.focused().should('not.have.attr', 'tabindex', '-1');

    // Verify skipped elements are not focused
    cy.get('[tabindex="-1"]').each(($element) => {
      cy.focused().should('not.equal', $element);
    });
  });

  it('should handle Shift+Tab for reverse navigation', () => {
    // Tab forward to an element
    cy.get('body').tab();
    cy.focused().then(($first) => {
      const firstElement = $first[0];

      // Tab forward once more
      cy.focused().tab();
      cy.focused().then(($second) => {
        const secondElement = $second[0];
        expect(secondElement).to.not.equal(firstElement);

        // Shift+Tab back
        cy.focused().tab({ shift: true });
        cy.focused().should('have.attr', 'tabindex').or('match', 'button, a, input, select, textarea');
      });
    });
  });

  it('should trap focus within modal when modal is open', () => {
    // Open a modal dialog
    cy.get('[data-testid="open-modal"]').click();
    cy.get('[role="dialog"]').should('be.visible');

    // Get all focusable elements within modal
    cy.get('[role="dialog"]').within(() => {
      cy.get('button, a, input, select, textarea, [tabindex]:not([tabindex="-1"])').then(($elements) => {
        const focusableCount = $elements.length;
        expect(focusableCount).to.be.greaterThan(0);
      });
    });

    // Tab through modal elements
    cy.get('[role="dialog"]').within(() => {
      cy.get('button, a, input, select, textarea').first().focus();
      cy.focused().should('exist');

      // Tab and verify focus stays within modal
      cy.focused().tab();
      cy.focused().closest('[role="dialog"]').should('exist');
    });
  });

  it('should maintain visible focus indicator for keyboard navigation', () => {
    cy.get('body').tab();

    // Verify focus is visible (has outline or other focus style)
    cy.focused().should(($element) => {
      const styles = window.getComputedStyle($element[0]);
      const hasOutline = styles.outline !== 'none' && styles.outline !== '';
      const hasBoxShadow = styles.boxShadow !== 'none' && styles.boxShadow !== '';
      const hasBorder = styles.borderWidth !== '0px';

      expect(hasOutline || hasBoxShadow || hasBorder).to.be.true;
    });

    // Tab to next element and verify focus indicator is visible
    cy.focused().tab();
    cy.focused().should(($element) => {
      const styles = window.getComputedStyle($element[0]);
      const isVisible = $element[0].offsetParent !== null;
      expect(isVisible).to.be.true;
    });
  });

  it('should handle dynamic content and maintain tab order', () => {
    // Add dynamic content
    cy.get('[data-testid="add-content"]').click();
    cy.get('[data-testid="dynamic-element"]').should('exist');

    // Tab through and verify new element is in focus order
    let foundDynamicElement = false;
    cy.get('body').tab();

    for (let i = 0; i < 10; i++) {
      cy.focused().then(($focused) => {
        if ($focused.attr('data-testid') === 'dynamic-element') {
          foundDynamicElement = true;
        }
      });
      cy.focused().tab();
    }

    cy.wrap(null).then(() => {
      expect(foundDynamicElement).to.be.true;
    });
  });

  it('should not allow tab navigation to disabled elements', () => {
    cy.get('button:disabled, input:disabled, select:disabled, textarea:disabled').each(($disabled) => {
      // Verify disabled elements are not in natural tab order
      cy.get('body').tab();
      cy.focused().should('not.equal', $disabled);
    });
  });

  it('should handle custom tab order with tabindex values', () => {
    // Elements with positive tabindex should be focused before natural order
    cy.get('[tabindex="1"]').should('exist');

    cy.get('body').tab();
    cy.focused().then(($first) => {
      const tabindex = $first.attr('tabindex');
      // First focused element should have tabindex or be first in natural order
      expect(tabindex === '1' || tabindex === null || tabindex === '0').to.be.true;
    });
  });
});
